// Format SAP maintenance order data into a structured report
const orders = $input.first().json.d.results;

const priorityLabel = (p) => {
  if (p === '1') return '🔴 Very High (P1)';
  if (p === '2') return '🟠 High (P2)';
  return `Priority ${p}`;
};

const statusLabel = (s) => {
  const map = {
    'CRTD': 'Created',
    'REL':  'Released',
    'PEND': 'Pending',
    'TECO': 'Technically Complete',
    'CLSD': 'Closed',
    'DLFL': 'Deletion Flag'
  };
  return map[s] || s;
};

const formatDate = (sapDate) => {
  if (!sapDate) return 'Not set';
  // SAP OData dates come as /Date(milliseconds)/
  const ms = parseInt(sapDate.replace(/\/Date\((\d+)\)\//, '$1'));
  if (isNaN(ms)) return sapDate;
  return new Date(ms).toLocaleDateString('en-GB', {
    day: '2-digit', month: 'short', year: 'numeric'
  });
};

const p1Orders = orders.filter(o => o.MaintPriority === '1');
const p2Orders = orders.filter(o => o.MaintPriority === '2');

// Build plain-text summary for AI
let summary = `SAP Plant Maintenance - High Priority Orders Report\n`;
summary += `Generated: ${new Date().toLocaleString('en-GB', {timeZone: 'Asia/Karachi'})} PKT\n`;
summary += `Total orders: ${orders.length} (P1: ${p1Orders.length}, P2: ${p2Orders.length})\n\n`;

orders.forEach(o => {
  summary += `Order: ${o.MaintenanceOrder}\n`;
  summary += `  Priority   : ${priorityLabel(o.MaintPriority)}\n`;
  summary += `  Type       : ${o.MaintOrderType}\n`;
  summary += `  Description: ${o.MaintOrderDesc || 'N/A'}\n`;
  summary += `  Plant      : ${o.MaintPlant}\n`;
  summary += `  Location   : ${o.FunctionalLocation || 'N/A'}\n`;
  summary += `  Equipment  : ${o.Equipment || 'N/A'}\n`;
  summary += `  Work Center: ${o.MainWorkCenter || 'N/A'}\n`;
  summary += `  Responsible: ${o.MaintOrdPersonResponsible || 'Unassigned'}\n`;
  summary += `  Start Date : ${formatDate(o.BasicStartDate)}\n`;
  summary += `  Due Date   : ${formatDate(o.BasicFinishDate)}\n`;
  summary += `  Status     : ${statusLabel(o.MaintOrderSystemStatus)}\n`;
  summary += `  Created    : ${formatDate(o.OrderCreationDate)}\n\n`;
});

// Build HTML table for email
let htmlRows = '';
orders.forEach(o => {
  const rowColor = o.MaintPriority === '1' ? '#ffe5e5' : '#fff3e0';
  htmlRows += `
    <tr style="background:${rowColor}">
      <td style="padding:8px;border:1px solid #ddd;font-weight:bold">${o.MaintenanceOrder}</td>
      <td style="padding:8px;border:1px solid #ddd">${priorityLabel(o.MaintPriority)}</td>
      <td style="padding:8px;border:1px solid #ddd">${o.MaintOrderType}</td>
      <td style="padding:8px;border:1px solid #ddd">${o.MaintOrderDesc || '-'}</td>
      <td style="padding:8px;border:1px solid #ddd">${o.MaintPlant}</td>
      <td style="padding:8px;border:1px solid #ddd">${o.FunctionalLocation || '-'}</td>
      <td style="padding:8px;border:1px solid #ddd">${o.Equipment || '-'}</td>
      <td style="padding:8px;border:1px solid #ddd">${o.MaintOrdPersonResponsible || 'Unassigned'}</td>
      <td style="padding:8px;border:1px solid #ddd">${formatDate(o.BasicStartDate)}</td>
      <td style="padding:8px;border:1px solid #ddd">${formatDate(o.BasicFinishDate)}</td>
      <td style="padding:8px;border:1px solid #ddd">${statusLabel(o.MaintOrderSystemStatus)}</td>
    </tr>`;
});

const htmlTable = `
<table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px">
  <thead>
    <tr style="background:#1a237e;color:white">
      <th style="padding:10px;border:1px solid #ddd">Order #</th>
      <th style="padding:10px;border:1px solid #ddd">Priority</th>
      <th style="padding:10px;border:1px solid #ddd">Type</th>
      <th style="padding:10px;border:1px solid #ddd">Description</th>
      <th style="padding:10px;border:1px solid #ddd">Plant</th>
      <th style="padding:10px;border:1px solid #ddd">Location</th>
      <th style="padding:10px;border:1px solid #ddd">Equipment</th>
      <th style="padding:10px;border:1px solid #ddd">Responsible</th>
      <th style="padding:10px;border:1px solid #ddd">Start Date</th>
      <th style="padding:10px;border:1px solid #ddd">Due Date</th>
      <th style="padding:10px;border:1px solid #ddd">Status</th>
    </tr>
  </thead>
  <tbody>${htmlRows}</tbody>
</table>`;

return [{
  json: {
    order_count: orders.length,
    p1_count: p1Orders.length,
    p2_count: p2Orders.length,
    orders: orders,
    plain_summary: summary,
    html_table: htmlTable,
    generated_at: new Date().toISOString()
  }
}];
